-- Description: Current active relationship for LNA_KIMBLEONEPERFORMANCEANALYSISC_COMPANY using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: CROSS_SOURCE_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNA_KIMBLEONEPERFORMANCEANALYSISC_COMPANY_HKEY AS LNA_KIMBLEONEPERFORMANCEANALYSISC_COMPANY_HKEY,
    l.KIMBLEONE__PERFORMANCEANALYSIS__C_HKEY AS KIMBLEONE__PERFORMANCEANALYSIS__C_HKEY,
    l.COMPANY_HKEY AS COMPANY_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.KIMBLEONE__PERFORMANCEANALYSIS__C_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_bv', 'lna_kimbleoneperformanceanalysisc_company') }} l
INNER JOIN {{ ref('las_sk_kimbleoneperformanceanalysisc_company_curr') }} ls
    ON l.LNA_KIMBLEONEPERFORMANCEANALYSISC_COMPANY_HKEY = ls.LNA_KIMBLEONEPERFORMANCEANALYSISC_COMPANY_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
